/* Embedded copies of the WebGL textures (Zippy sprite, city skyline, scooter rider).
   WebGL cannot read image files when index.html is opened straight from disk (file://),
   so these stay inline.  */
window.TEXTURES = {
  zippy: "data:image/webp;base64,",
  backdrop: "data:image/webp;base64,",
  rider: "data:image/webp;base64,"
};
